17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
29	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.util.StringUtils;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    /**
71	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
72	     * and a domain containing at least one dot, with no whitespace in any segment.
73	     */
74	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        validateRequiredFields(ownerFieldsDto);
115	        HttpHeaders headers = new HttpHeaders();
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
118	        requireUniqueTelephone(telephone);
119	        owner.setTelephone(telephone);
120	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
121	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
122	        this.clinicService.saveOwner(owner);
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    /**
130	     * Generates the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}.
131	     * {@code LAST3} is the upper-cased first three letters of the last name and {@code NNNN} is a
132	     * global, 4-digit zero-padded sequence equal to one more than the current number of owners
133	     * (e.g. {@code 'SMI-0007'}).
134	     *
135	     * @param lastName the owner's last name
136	     * @return the generated customer code
137	     */
138	    private String generateCustomerCode(String lastName) {
139	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
140	        int sequence = this.clinicService.findAllOwners().size() + 1;
141	        return String.format("%s-%04d", last3, sequence);
142	    }
143	
144	    /**
145	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
146	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
147	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
148	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
149	     *
150	     * @param ownerFieldsDto the submitted owner fields
151	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
152	     */
153	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
154	        List<String> invalidFields = new ArrayList<>();
155	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
156	            invalidFields.add("firstName");
157	        }
158	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
159	            invalidFields.add("lastName");
160	        }
161	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
162	            invalidFields.add("address");
163	        }
164	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
165	            invalidFields.add("city");
166	        }
167	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
168	            invalidFields.add("telephone");
169	        }
170	        if (!invalidFields.isEmpty()) {
171	            throw new InvalidOwnerFieldsException(invalidFields);
172	        }
173	    }
174	
175	    /**
176	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
177	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
178	     * what gets stored and returned.
179	     *
180	     * @param telephone the raw telephone value from the request
181	     * @return the normalized E.164 telephone number
182	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
183	     */
184	    private String normalizeTelephone(String telephone) {
185	        String e164 = toE164(telephone);
186	        if (e164 == null) {
187	            throw new InvalidOwnerFieldsException(List.of("telephone"));
188	        }
189	        return e164;
190	    }
191	
192	    /**
193	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
194	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
195	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
196	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
197	     * it contains 8 to 15 digits after the {@code '+'}.
198	     *
199	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
200	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
201	     *
202	     * @param telephone the raw telephone value, possibly {@code null}
203	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
204	     */
205	    private String toE164(String telephone) {
206	        if (telephone == null) {
207	            return null;
208	        }
209	        String cleaned = telephone.replaceAll("[ \\-()]", "");
210	        String digits;
211	        if (cleaned.startsWith("+")) {
212	            digits = cleaned.substring(1);
213	        } else {
214	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
215	            digits = "61" + national;
216	        }
217	        if (!digits.matches("[0-9]{8,15}")) {
218	            return null;
219	        }
220	        return "+" + digits;
221	    }
222	
223	    /**
224	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
225	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
226	     * and returned lower-cased.
227	     *
228	     * @param email the raw email value from the request, possibly {@code null}
229	     * @return the lower-cased email, or {@code null} when none was supplied
230	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
231	     */
232	    private String normalizeEmail(String email) {
233	        if (!StringUtils.hasText(email)) {
234	            return null;
235	        }
236	        String trimmed = email.trim();
237	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
238	            throw new InvalidOwnerFieldsException(List.of("email"));
239	        }
240	        return trimmed.toLowerCase(Locale.ROOT);
241	    }
242	
243	    /**
244	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
245	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
246	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
247	     *
248	     * @param telephone the normalized (E.164) telephone of the owner being created
249	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
250	     */
251	    private void requireUniqueTelephone(String telephone) {
252	        boolean inUse = this.clinicService.findAllOwners().stream()
253	            .map(Owner::getTelephone)
254	            .filter(existing -> existing != null)
255	            .map(existing -> {
256	                String e164 = toE164(existing);
257	                return e164 != null ? e164 : existing;
258	            })
259	            .anyMatch(telephone::equals);
260	        if (inUse) {
261	            throw new DuplicateTelephoneException(telephone);
262	        }
263	    }
264	
265	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
266	    @Override
267	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
268	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
269	        if (currentOwner == null) {
270	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	        }
272	        currentOwner.setAddress(ownerFieldsDto.getAddress());
273	        currentOwner.setCity(ownerFieldsDto.getCity());
274	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
275	        currentOwner.setLastName(ownerFieldsDto.getLastName());
276	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
277	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
278	        this.clinicService.saveOwner(currentOwner);
279	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
280	    }
281	
282	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
283	    @Transactional
284	    @Override
285	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
286	        Owner owner = this.clinicService.findOwnerById(ownerId);
287	        if (owner == null) {
288	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
289	        }
290	        this.clinicService.deleteOwner(owner);
291	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
292	    }
293	
294	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
295	    @Override
296	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
297	        Owner owner = this.clinicService.findOwnerById(ownerId);
298	        if (owner == null) {
299	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
300	        }
301	        HttpHeaders headers = new HttpHeaders();
302	        Pet pet = petMapper.toPet(petFieldsDto);
303	        owner.setId(ownerId);
304	        pet.setOwner(owner);
305	        pet.getType().setName(null);
306	        this.clinicService.savePet(pet);
307	        PetDto petDto = petMapper.toPetDto(pet);
308	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
309	            .buildAndExpand(pet.getId()).toUri());
310	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
311	    }
312	
313	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
314	    @Override
315	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
316	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
317	        if (currentOwner != null) {
318	            Pet currentPet = this.clinicService.findPetById(petId);
319	            if (currentPet != null) {
320	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
321	                currentPet.setName(petFieldsDto.getName());
322	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
323	                this.clinicService.savePet(currentPet);
324	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
325	            }
326	        }
327	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
328	    }
329	
330	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
331	    @Override
332	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
333	        HttpHeaders headers = new HttpHeaders();
334	        Visit visit = visitMapper.toVisit(visitFieldsDto);
335	        Pet pet = new Pet();
336	        pet.setId(petId);
337	        visit.setPet(pet);
338	        this.clinicService.saveVisit(visit);
339	        VisitDto visitDto = visitMapper.toVisitDto(visit);
340	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
341	            .buildAndExpand(visit.getId()).toUri());
342	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
343	    }
344	
345	
346	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
347	    @Override
348	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
349	        Owner owner = this.clinicService.findOwnerById(ownerId);
350	        if (owner != null) {
351	            Pet pet = owner.getPet(petId);
352	            if (pet != null) {
353	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
354	            }
355	        }
356	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
357	    }
358	}
